func BoutsOf(id int) int      { return must(id).bouts }
func PoolOf(id int) int64     { return must(id).pool }
func Listed(id int) bool      { return must(id).listed }
func InMatch(id int) bool     { return must(id).inMatch }
func LayOpen(id int) bool     { return must(id).layOpen }
func RarityOf(id int) string  { return must(id).rarity }
func SizeOf(id int) string    { return must(id).size }
func TraitOf(id int) string   { return must(id).trait }
func SpeciesOf(id int) string { return must(id).species }

func issue(to address, name, rarity, size, trait string) int {
	nextID++
	id := nextID
	maxHP := hpOf(rarity, size, trait)
	body := &fishBody{
		id:      id,
		name:    name,
		rarity:  rarity,
		species: speciesOf(rarity),
		size:    size,
		trait:   trait,
		hp:      maxHP,
		hpNow:   maxHP,
		dodge:           dodgeOf(size),
		faceDx:          0,
		faceDz:          -1,
		aspectBps:       10000,
		springBorn:      -1,
		lastCombatMilli: -1,
		owner:           to,
		image:   artOf(rarity),
	}
	for len(bodies) <= id {
		bodies = append(bodies, nil)
	}
	bodies[id] = body
	minted++
	mintGRC(to, body)
	return id
}

func mintGRC(to address, body *fishBody) {
	tid := tokenID(body.id)
	if err := ledger.Mint(to, tid); err != nil {
		panic("fish: mint")
	}
	writeURI(body)
}

func writeURI(body *fishBody) {
	if err := metaLed.SetTokenURI(tokenID(body.id), tokenJSON(body)); err != nil {
		panic("fish: uri")
	}
}

func artOf(rarity string) string {
	if portrait != "" {
		return portrait
	}
	return imageBase + "/" + rarity + ".png"
}

func burnGRC(id int) {
	if err := ledger.Burn(tokenID(id)); err != nil {
		panic("fish: burn")
	}
}

func moveToken(spender, from, to address, id int) {
	if err := ledger.TransferFrom(spender, from, to, tokenID(id)); err != nil {
		panic("fish: transfer")
	}
}

func tokenJSON(body *fishBody) string {
	return "data:application/json;charset=utf-8," +
		`{"name":"` + body.name + `","description":"Shoal fish","image":"` + body.image +
		`","attributes":[{"trait_type":"Species","value":"` + body.species +
		`"},{"trait_type":"Size","value":"` + body.size +
		`"},{"trait_type":"Trait","value":"` + body.trait +
		`"},{"trait_type":"Rarity","value":"` + body.rarity +
		`"},{"trait_type":"HP","value":"` + strconv.Itoa(body.hp) + `"}]}`
}

func requireUser(cur realm) address {
	if !cur.IsCurrent() {
		panic("fish: realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("fish: eoa")
	}
	return cur.Previous().Address()
}

func requireInit() {
	if !inited || token == nil {
		panic("fish: init")
	}
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("fish: payment")
		}
		return
	}
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount != n {
		panic("fish: payment")
	}
}

func payMint(fee int64, rlm realm) {
	up := fee * 6000 / 10000
	lp := fee * 2000 / 10000
	team := fee * 1000 / 10000
	burn := fee - up - lp - team
	send(upgradeSink, up, rlm)
	send(lpSink, lp, rlm)
	send(teamSink, team, rlm)
	send(burnSink, burn, rlm)
}

func fishTokenReady() bool {
	return self != address("") && shoaltoken.Sealed() && shoaltoken.Spender() == self
}

func send(to address, amt int64, rlm realm) {
	if amt == 0 {
		return
	}
	if !to.IsValid() {
		panic("fish: sink")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: denom, Amount: amt}})
}

func must(id int) *fishBody {
	requireInit()
	if id < 1 || id >= len(bodies) || bodies[id] == nil || bodies[id].burned {
		panic("fish: unknown")
	}
	return bodies[id]
}

func guardMovable(body *fishBody) {
	if body.listed {
		panic("fish: listed")
	}
	if body.inMatch {
		panic("fish: match")
	}
	if body.pool != 0 {
		panic("fish: pool")
	}
	if body.layOpen {
		panic("fish: lay")
	}
}

func unplayed(owner address) bool {
	for _, body := range bodies {
		if body == nil || body.burned || body.bouts >= 1 {
			continue
		}
		if body.owner == owner || (body.listed && body.seller == owner) {
			return true
		}
	}
	return false
}

func tokenID(id int) grc721.TokenID {
	return grc721.TokenID(strconv.Itoa(id))
}

func parseID(tid string) int {
	id, err := strconv.Atoi(tid)
	if err != nil || id < 1 {
		panic("fish: unknown")
	}
	return id
}

func validFishName(name string) bool {
	if len(name) < 1 || len(name) > 20 {
		return false
	}
	for _, c := range name {
		if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') && (c < '0' || c > '9') && c != ' ' {
			return false
		}
	}
	return true
}

func validCollectionName(name string) bool {
	return name != "" && len(name) <= 64 && !strings.Contains(name, "|")
}

func validArt(image string) bool {
	if !strings.HasPrefix(image, "https://") || len(image) > 160 || strings.Contains(image, "|") {
		return false
	}
	if strings.Contains(image, `"`) || strings.Contains(image, "\n") || strings.Contains(image, "\\") {
		return false
	}
	return true
}

func validSymbol(symbol string) bool {
	if symbol == "" || len(symbol) > grc721.MaxSymbolLen {
		return false
	}
	for _, c := range symbol {
		if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') && (c < '0' || c > '9') {
			return false
		}
	}
	return true
}

func validSize(size string) bool {
	return size == "small" || size == "medium" || size == "large"
}

func validTrait(trait string) bool {
	return trait == "swift" || trait == "fang" || trait == "hide"
}

func speciesOf(rarity string) string {
	switch rarity {
	case "common":
		return "Minnow"
	case "uncommon":
		return "Mackerel"
	case "rare":
		return "Snapper"
	case "epic":
		return "Angler"
	case "legendary":
		return "Koi Dragon"
	case "mythic":
		return "Abyss Leviathan"
	default:
		panic("fish: rarity")
	}
}

func hpBase(rarity string) int {
	switch rarity {
	case "common":
		return 100
	case "uncommon":
		return 112
	case "rare":
		return 126
	case "epic":
		return 142
	case "legendary":
		return 160
	case "mythic":
		return 180
	default:
		panic("fish: rarity")
	}
}

func hpOf(rarity, size, trait string) int {
	hp := hpBase(rarity)
	if size == "small" {
		hp = hp * 88 / 100
	}
	if size == "large" {
		hp = hp * 120 / 100
	}
	if trait == "hide" {
		hp = hp * 112 / 100
	}
	if hp < 1 {
		hp = 1
	}
	return hp
}

func dodgeOf(size string) int {
	if size == "small" {
		return 24
	}
	return 0
}

func arenaStake(stake int64) bool {
	return stake >= stakeMin && stake <= stakeCeil
}

package fishtry

import (
	"chain/runtime"
	"crypto/sha256"
	"strconv"
	"time"

	shoaltoken "gno.land/r/g10ragdr3cjqkael8rslpw4y6rlelhev4h0fswcx/fishcoin"
)

func Register(cur realm, id int, stake int64) {
	caller := requireUser(cur)
	body := must(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	if body.inMatch {
		panic("fish: match")
	}
	if body.mustHeal {
		panic("fish: heal")
	}
	guardMovable(body)
	if tooHurt(body) {
		panic("fish: hp")
	}
	if walletInSea(caller) {
		panic("fish: one")
	}
	if !arenaStake(stake) {
		panic("fish: stake")
	}
	takeExact(stake)
	now := time.Now().Unix()
	body.pool = stake
	body.inMatch = true
	body.boutPaid = false
	body.startUnix = now
	body.endUnix = 0
	body.lastCombatMilli = -1
	body.nextMoveMilli = 0
	body.burstUntil = 0
	body.nextBurstAt = 0
	body.springBorn = -1
	placeSwimmer(body)
	clearDamage(id)
}

func Leave(cur realm, id int) {
	caller := requireUser(cur)
	takeExact(0)
	body := must(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	if !body.inMatch {
		panic("fish: match")
	}
	nowMs := time.Now().UnixMilli()
	if body.lastCombatMilli >= 0 && nowMs < body.lastCombatMilli+combatLockMs {
		panic("fish: stay")
	}
	returnCheers(body, cur)
	stake := body.pool
	body.pool = 0
	body.inMatch = false
	body.boutPaid = false
	clearDamage(id)
	send(caller, stake, cur)
}

func SettleMatch(cur realm, id int) {
	requireUser(cur)
	takeExact(0)
	body := must(id)
	if !body.inMatch {
		panic("fish: match")
	}
	_ = body
	panic("fish: sea")
}

func CommitLay(cur realm, id int) {
	caller := requireUser(cur)
	body := must(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	guardMovable(body)
	left := body.bouts - body.layBoutsUsed
	if left < 3 {
		panic("fish: bouts")
	}
	takeExact(layFee)
	payMint(layFee, cur)
	body.layBoutsUsed = body.bouts
	body.layOpen = true
	body.layHeight = runtime.ChainHeight()
}

func SettleLay(cur realm, id int) int {
	requireUser(cur)
	takeExact(0)
	body := must(id)
	if !body.layOpen {
		panic("fish: lay")
	}
	height := runtime.ChainHeight()
	if height < body.layHeight+layBlocks {
		panic("fish: early")
	}
	trait := traitFrom(body.id, body.layHeight, height, time.Now().Unix())
	body.layOpen = false
	return issue(body.owner, body.name+" fry", body.rarity, body.size, trait)
}

// Upgrade spends 15 FISH to step two played Common fish to Uncommon.
// The FISH fee burns. The team takes none of it. No GNOT moves.
// Higher tiers stay closed until a commit-reveal roll exists.
func Upgrade(cur realm, keep, food int) int {
	caller := requireUser(cur)
	if keep == food {
		panic("fish: upgrade")
	}
	a := must(keep)
	b := must(food)
	if a.owner != caller || b.owner != caller {
		panic("fish: owner")
	}
	guardMovable(a)
	guardMovable(b)
	if a.rarity != b.rarity || a.size != b.size || a.trait != b.trait {
		panic("fish: pair")
	}
	if a.bouts < 1 || b.bouts < 1 {
		panic("fish: bouts")
	}
	if a.rarity != "common" {
		panic("fish: roll")
	}
	takeExact(0)
	if !fishTokenReady() {
		panic("fish: fish")
	}
	got := shoaltoken.Draw(cross(cur), caller, burnSink, upgradeFishFee)
	if got != upgradeFishFee {
		panic("fish: fish")
	}
	name := a.name
	size := a.size
	trait := a.trait
	burnBody(a)
	burnBody(b)
	return issue(caller, name, "uncommon", size, trait)
}

func burnBody(body *fishBody) {
	burnGRC(body.id)
	body.burned = true
	body.owner = address("")
	body.seller = address("")
	body.price = 0
	body.listed = false
	body.pool = 0
	body.inMatch = false
	body.layOpen = false
}

func traitFrom(id int, commitHeight, settleHeight, unix int64) string {
	raw := strconv.Itoa(id) + ":" + strconv.FormatInt(commitHeight, 10) + ":" + strconv.FormatInt(settleHeight, 10) + ":" + strconv.FormatInt(unix, 10)
	sum := sha256.Sum256([]byte(raw))
	var n int64
	for i := 0; i < len(sum); i++ {
		n = (n*256 + int64(sum[i])) % 3
	}
	switch n {
	case 0:
		return "swift"
	case 1:
		return "fang"
	default:
		return "hide"
	}
}

package fishtry

import (
	"chain/runtime/unsafe"
	"math"
	"time"
)

// One shared sea. Cells are 8 world units. A sector center is the chain position.
// Springs and shelter discs use the same layout as the practice sea. No RNG.

const (
	seaRadius         = 360
	sector            = 8
	unitMilli         = 1000
	sectorMilli       = 8000
	mouthAlignNum     = 552264
	mouthContact      = 1000
	healsPerDay       = 2
	healPercent       = 40
	healCooldownMs    = 8 * 3600 * 1000
	ictOffsetMs       = 7 * 3600 * 1000
	dayMs             = 24 * 3600 * 1000
	springPeriodMs    = 20000
	springLifeMs      = 15000
	springRadiusMilli = 3000
	springHealPercent = 20
	shelterHPMax      = 64
	shelterRebuildMs  = 20000
	burstWindowMs     = 1000
	burstCoolMs       = 2000
	viewerShards      = 10
	viewerWatchMs     = 15000
	viewerWindowMs    = 30000
	minCheer          = ugnot
	growMediumAt      = 2
	growLargeAt       = 4
	growEvolveAt      = 6
)

type cheerRow struct {
	fish   int
	who    address
	amount int64
	live   bool
}

type claimRow struct {
	who     address
	amount  int64
	kind    string
	killAt  int64
	expires int64
	claimed bool
	killer  address
	victim  address
	killID  int
}

type watchRow struct {
	who   address
	since int64
}

type disc struct {
	x     int
	z     int
	r     int
	inner int
	kind  string
}

var (
	cheers      []cheerRow
	claims      []claimRow
	watches     []watchRow
	killSeq     int
	shelterHP   []int
	shelterDown []int64
	shelterTable = []disc{
		{x: 96_000, z: 8_000, inner: 5_200, kind: "reef"},
		{x: -120_000, z: 72_000, inner: 5_600, kind: "reef"},
		{x: 28_000, z: -110_000, inner: 4_400, kind: "cave"},
		{x: -140_000, z: 150_000, inner: 4_400, kind: "cave"},
	}
	rockTable = []disc{
		{x: 18_000, z: -24_000, r: 3_600},
		{x: -8_000, z: 48_000, r: 3_600},
		{x: 120_000, z: -48_000, r: 4_200},
	}
)

func Turn(cur realm, id, dx, dz int) {
	caller := requireUser(cur)
	takeExact(0)
	body := must(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	if !body.inMatch || body.pool <= 0 {
		panic("fish: match")
	}
	if dx < -1 || dx > 1 || dz < -1 || dz > 1 || (dx == 0 && dz == 0) {
		panic("fish: face")
	}
	body.faceDx = dx
	body.faceDz = dz
}

func Move(cur realm, id int) {
	caller := requireUser(cur)
	takeExact(0)
	body := swimming(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	now := time.Now().UnixMilli()
	if now < body.nextMoveMilli {
		panic("fish: move")
	}
	stepFish(body, now)
}

func Burst(cur realm, id int) {
	caller := requireUser(cur)
	takeExact(0)
	body := swimming(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	now := time.Now().UnixMilli()
	if now < body.nextBurstAt {
		return
	}
	body.burstUntil = now + burstWindowMs
	body.nextBurstAt = body.burstUntil + burstCoolMs
}

func Heal(cur realm, id int) {
	caller := requireUser(cur)
	takeExact(0)
	body := must(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	if body.inMatch {
		panic("fish: match")
	}
	now := time.Now().UnixMilli()
	day, used, ready := rolledHeal(body, now)
	if body.hpNow >= body.hp && !body.mustHeal {
		panic("fish: hp")
	}
	if used >= healsPerDay || now < ready {
		panic("fish: heal")
	}
	used++
	if used >= healsPerDay {
		ready = now + healCooldownMs
	}
	writeHeal(body, day, used, ready)
	gain := body.hp * healPercent / 100
	body.hpNow += gain
	if body.hpNow > body.hp {
		body.hpNow = body.hp
	}
	if body.hpNow < 1 {
		body.hpNow = 1
	}
	body.mustHeal = false
}

func RushHeal(cur realm, id int) {
	caller := requireUser(cur)
	body := must(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	now := time.Now().UnixMilli()
	day, used, ready := rolledHeal(body, now)
	if used < healsPerDay || now >= ready {
		panic("fish: heal")
	}
	remaining := ready - now
	cost := int64(tierOf(body.rarity)) * remaining * ugnot / (16 * 3_600_000)
	takeExact(cost)
	writeHeal(body, day, healsPerDay-1, 0)
	send(burnSink, cost, cur)
}

// Cheer locks ugnot on a fish already in the sea. The deposit comes back when
// that fish leaves or is downed. It does not change bite.
func Cheer(cur realm, id int) {
	caller := requireUser(cur)
	body := must(id)
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount < minCheer {
		panic("fish: payment")
	}
	amount := sent[0].Amount
	if caller == body.owner {
		panic("fish: cheer")
	}
	if !liveFish(body, time.Now().Unix()) {
		panic("fish: match")
	}
	if cheerLocked(id)+amount > body.pool/2 {
		panic("fish: cap")
	}
	cheers = append(cheers, cheerRow{fish: id, who: caller, amount: amount, live: true})
}

func Watch(cur realm, on bool) {
	caller := requireUser(cur)
	takeExact(0)
	if !on {
		dropWatch(caller)
		return
	}
	for i := range watches {
		if watches[i].who == caller {
			return
		}
	}
	watches = append(watches, watchRow{who: caller, since: time.Now().UnixMilli()})
}

func Claim(cur realm, id int) {
	caller := requireUser(cur)
	takeExact(0)
	if id < 1 || id > len(claims) {
		panic("fish: claim")
	}
	row := &claims[id-1]
	if row.claimed {
		panic("fish: claim")
	}
	now := time.Now().UnixMilli()
	if row.expires > 0 && now >= row.expires {
		amt := row.amount
		row.claimed = true
		row.amount = 0
		send(seasonSink, amt, cur)
		return
	}
	if row.kind == "watch" {
		if caller == row.killer || caller == row.victim {
			panic("fish: claim")
		}
		if !watchEligible(caller, row.killAt) {
			panic("fish: watch")
		}
		if watchClaimed(caller, row.killID) {
			panic("fish: claim")
		}
		row.who = caller
	} else if row.who != caller {
		panic("fish: owner")
	}
	amt := row.amount
	row.claimed = true
	row.amount = 0
	send(caller, amt, cur)
}

func swimming(id int) *fishBody {
	body := must(id)
	if !liveFish(body, time.Now().Unix()) {
		panic("fish: match")
	}
	if body.mustHeal {
		panic("fish: heal")
	}
	return body
}

func walletInSea(owner address) bool {
	for _, body := range bodies {
		if body == nil || body.burned || !body.inMatch {
			continue
		}
		if body.owner == owner {
			return true
		}
	}
	return false
}

func tooHurt(body *fishBody) bool {
	if body.hp <= 0 {
		return true
	}
	return body.hpNow*100 < body.hp*30
}

func placeSwimmer(body *fishBody) {
	ensureSea()
	for sx := 0; sx < 90; sx++ {
		if tryPlace(body, sx, 0) {
			return
		}
	}
	for sz := 1; sz < 40; sz++ {
		for sx := -40; sx < 40; sx++ {
			if tryPlace(body, sx, sz) {
				return
			}
		}
	}
	panic("fish: sea")
}

func tryPlace(body *fishBody, sx, sz int) bool {
	if spawnBlocked(sx, sz) || cellTaken(sx, sz, body.id) {
		return false
	}
	body.sx = sx
	body.sz = sz
	body.faceDx = 0
	body.faceDz = -1
	return true
}

func stepFish(body *fishBody, now int64) {
	if body.faceDx == 0 && body.faceDz == 0 {
		panic("fish: face")
	}
	nx := body.sx + body.faceDx
	nz := body.sz + body.faceDz
	if !sectorInSea(nx, nz) {
		panic("fish: sea")
	}
	if cellBlocked(nx, nz, body.size, now) {
		panic("fish: cover")
	}
	body.sx = nx
	body.sz = nz
	body.nextMoveMilli = now + moveDelay(body, now)
	touchSpring(body, now)
}

func sectorInSea(sx, sz int) bool {
	x, z := cellMilli(sx, sz)
	dx := int64(x)
	dz := int64(z)
	limit := int64(seaRadius * unitMilli)
	return dx*dx+dz*dz <= limit*limit
}

func cellTaken(sx, sz, self int) bool {
	for _, body := range bodies {
		if body == nil || body.burned || body.id == self || !body.inMatch {
			continue
		}
		if body.sx == sx && body.sz == sz {
			return true
		}
	}
	return false
}

func spawnBlocked(sx, sz int) bool {
	if !sectorInSea(sx, sz) {
		return true
	}
	ensureSea()
	for i := range rockTable {
		if discHolds(sx, sz, rockTable[i].x, rockTable[i].z, rockTable[i].r) {
			return true
		}
	}
	now := time.Now().UnixMilli()
	for i := range shelterTable {
		refreshShelter(i, now)
		if shelterHP[i] <= 0 {
			continue
		}
		if discHolds(sx, sz, shelterTable[i].x, shelterTable[i].z, shelterTable[i].inner) {
			return true
		}
	}
	return false
}

func cellBlocked(sx, sz int, size string, now int64) bool {
	if !sectorInSea(sx, sz) {
		return true
	}
	ensureSea()
	for i := range rockTable {
		if discHolds(sx, sz, rockTable[i].x, rockTable[i].z, rockTable[i].r) {
			return true
		}
	}
	for i := range shelterTable {
		refreshShelter(i, now)
		if shelterHP[i] <= 0 || shelterAdmits(shelterTable[i].kind, size) {
			continue
		}
		if discHolds(sx, sz, shelterTable[i].x, shelterTable[i].z, shelterTable[i].inner) {
			return true
		}
	}
	return false
}

func cellMilli(sx, sz int) (int, int) {
	return sx*sectorMilli + sectorMilli/2, sz*sectorMilli + sectorMilli/2
}

func insideDisc(x, z, cx, cz, r int) bool {
	dx := int64(x - cx)
	dz := int64(z - cz)
	rr := int64(r)
	return dx*dx+dz*dz <= rr*rr
}

func ensureSea() {
	if len(shelterHP) == len(shelterTable) && len(shelterDown) == len(shelterTable) {
		return
	}
	shelterHP = make([]int, len(shelterTable))
	shelterDown = make([]int64, len(shelterTable))
	for i := range shelterHP {
		shelterHP[i] = shelterHPMax
	}
}

func refreshShelter(i int, now int64) {
	ensureSea()
	if shelterHP[i] > 0 {
		return
	}
	if shelterDown[i] > 0 && now >= shelterDown[i] {
		shelterHP[i] = shelterHPMax
		shelterDown[i] = 0
	}
}

func shelterAdmits(kind, size string) bool {
	if size == "large" {
		return false
	}
	if kind == "cave" {
		return size == "small"
	}
	return size == "small" || size == "medium"
}

func coverIndex(body *fishBody, now int64) int {
	ensureSea()
	for i := range shelterTable {
		refreshShelter(i, now)
		if shelterHP[i] <= 0 || !shelterAdmits(shelterTable[i].kind, body.size) {
			continue
		}
		if discHolds(body.sx, body.sz, shelterTable[i].x, shelterTable[i].z, shelterTable[i].inner) {
			return i
		}
	}
	return -1
}

func redirectShelter(atk, vic *fishBody, now int64) bool {
	idx := coverIndex(vic, now)
	if idx < 0 || shelterAdmits(shelterTable[idx].kind, atk.size) {
		return false
	}
	if discHolds(atk.sx, atk.sz, shelterTable[idx].x, shelterTable[idx].z, shelterTable[idx].inner) {
		return false
	}
	dmg := strikeDamage(biteNow(atk), shelterHPMax, atk.size, "medium")
	if dmg > shelterHP[idx] {
		dmg = shelterHP[idx]
	}
	shelterHP[idx] -= dmg
	if shelterHP[idx] <= 0 {
		shelterHP[idx] = 0
		shelterDown[idx] = now + shelterRebuildMs
	}
	return true
}

func mouthHit(atk, def *fishBody) bool {
	return mouthAimed(atk, def, def.dodge)
}

// shelterMouth is a bite against the pocket, not against the fish's dodge.
// The attacker must stand outside, must not fit inside, and must face the fish.
func shelterMouth(atk, vic *fishBody, now int64) bool {
	idx := coverIndex(vic, now)
	if idx < 0 || shelterAdmits(shelterTable[idx].kind, atk.size) {
		return false
	}
	if discHolds(atk.sx, atk.sz, shelterTable[idx].x, shelterTable[idx].z, shelterTable[idx].inner) {
		return false
	}
	return mouthAimed(atk, vic, 0)
}

// Sector centers sit off the practice discs, same as a spring on z = 0.
// The cell that holds the point counts as inside.
func discHolds(sx, sz, cx, cz, r int) bool {
	x, z := cellMilli(sx, sz)
	if insideDisc(x, z, cx, cz, r) {
		return true
	}
	px := int(math.Floor(float64(cx) / float64(sectorMilli)))
	pz := int(math.Floor(float64(cz) / float64(sectorMilli)))
	return sx == px && sz == pz
}

func mouthAimed(atk, def *fishBody, dodge int) bool {
	if !inReachDodge(atk, def, dodge) {
		return false
	}
	ax, az := cellMilli(atk.sx, atk.sz)
	bx, bz := cellMilli(def.sx, def.sz)
	dx := bx - ax
	dz := bz - az
	dist2 := int64(dx)*int64(dx) + int64(dz)*int64(dz)
	if dist2 <= int64(mouthContact)*int64(mouthContact) {
		return true
	}
	fx, fz := faceMilli(atk.faceDx, atk.faceDz)
	lead := mouthLead(atk.size)
	mx := dx - fx*lead/1000
	mz := dz - fz*lead/1000
	mouth2 := int64(mx)*int64(mx) + int64(mz)*int64(mz)
	if mouth2 == 0 {
		return true
	}
	dot := int64(mx)*int64(fx) + int64(mz)*int64(fz)
	if dot <= 0 {
		return false
	}
	return dot*dot >= int64(mouthAlignNum)*mouth2
}

func faceMilli(dx, dz int) (int, int) {
	if dx == 0 && dz == 0 {
		return 0, -1000
	}
	span := dx*dx + dz*dz
	if span == 1 {
		return dx * 1000, dz * 1000
	}
	if span == 2 {
		sx := 707
		sz := 707
		if dx < 0 {
			sx = -707
		}
		if dz < 0 {
			sz = -707
		}
		return sx, sz
	}
	return 0, -1000
}

func mouthLead(size string) int {
	switch size {
	case "small":
		return 700
	case "large":
		return 1450
	default:
		return 1000
	}
}

func biteNow(body *fishBody) int {
	b := biteOf(body.rarity, body.size, body.trait)
	if body.evolved && body.aspectBps > 0 {
		b = (b*body.aspectBps + 5000) / 10000
	}
	if b < 1 {
		return 1
	}
	return b
}

func strikeFought(bite, hpMax int, atkSize, defSize, atkR, defR string) int {
	_ = atkSize
	_ = defSize
	_ = atkR
	_ = defR
	dmg := bite * 100 / (hpMax + 100)
	if dmg < 1 {
		dmg = 1
	}
	return dmg
}

func preyOf(rarity string) string {
	switch rarity {
	case "common":
		return "mythic"
	case "uncommon":
		return "common"
	case "rare":
		return "uncommon"
	case "epic":
		return "rare"
	case "legendary":
		return "epic"
	case "mythic":
		return "legendary"
	default:
		panic("fish: rarity")
	}
}

func nextRarity(rarity string) string {
	switch rarity {
	case "common":
		return "uncommon"
	case "uncommon":
		return "rare"
	case "rare":
		return "epic"
	case "epic":
		return "legendary"
	case "legendary":
		return "mythic"
	default:
		return ""
	}
}

func growFromKill(atk, vic *fishBody) {
	if sizeIndex(vic.size) >= sizeIndex(atk.size)+1 {
		atk.growth += 2
	} else {
		atk.growth++
	}
	next := atk.size
	if next == "small" && atk.growth >= growMediumAt {
		next = "medium"
	}
	if next == "medium" && atk.growth >= growLargeAt {
		next = "large"
	}
	if next != atk.size {
		old := atk.hp
		if old < 1 {
			old = 1
		}
		atk.size = next
		atk.hp = hpOf(atk.rarity, next, atk.trait)
		atk.dodge = dodgeOf(next)
		atk.hpNow = atk.hpNow * atk.hp / old
		if atk.hpNow < 1 {
			atk.hpNow = 1
		}
		if atk.hpNow > atk.hp {
			atk.hpNow = atk.hp
		}
	}
	if atk.evolved || atk.size != "large" || atk.growth < growEvolveAt {
		return
	}
	aspect := nextRarity(atk.rarity)
	if aspect == "" {
		return
	}
	atk.evolved = true
	atk.aspect = aspect
	atk.aspectBps = 10800
	atk.hp = (atk.hp*108 + 50) / 100
	if atk.hp < 1 {
		atk.hp = 1
	}
	atk.hpNow = (atk.hpNow*108 + 50) / 100
	if atk.hpNow < 1 {
		atk.hpNow = 1
	}
	if atk.hpNow > atk.hp {
		atk.hpNow = atk.hp
	}
}

func worldSpeed(body *fishBody) int {
	base := 100
	switch body.rarity {
	case "common":
		base = 100
	case "uncommon":
		base = 97
	case "rare":
		base = 94
	case "epic":
		base = 91
	case "legendary":
		base = 88
	case "mythic":
		base = 85
	default:
		panic("fish: rarity")
	}
	units := base * 220 / 1000
	if body.size == "small" {
		units = units * 116 / 100
	}
	if body.size == "large" {
		units = units * 88 / 100
	}
	if body.trait == "swift" {
		units = units * 112 / 100
	}
	if units < 1 {
		return 1
	}
	return units
}

func moveDelay(body *fishBody, now int64) int64 {
	units := worldSpeed(body)
	if now < body.burstUntil {
		units = units * 7 / 4
	}
	if units < 1 {
		units = 1
	}
	delay := int64(sector*1000) / int64(units)
	if delay < 1 {
		return 1
	}
	return delay
}

func tierOf(rarity string) int {
	switch rarity {
	case "common":
		return 1
	case "uncommon":
		return 2
	case "rare":
		return 3
	case "epic":
		return 4
	case "legendary":
		return 5
	case "mythic":
		return 6
	default:
		panic("fish: rarity")
	}
}

func rolledHeal(body *fishBody, now int64) (day int64, used int, ready int64) {
	day = (now + ictOffsetMs) / dayMs
	used = body.healsUsed
	ready = body.healReadyAt
	if body.healDay != day {
		used = 0
		ready = 0
	}
	if used >= healsPerDay && ready > 0 && now >= ready {
		used = healsPerDay - 1
		ready = 0
	}
	return
}

func writeHeal(body *fishBody, day int64, used int, ready int64) {
	body.healDay = day
	body.healsUsed = used
	body.healReadyAt = ready
}

func cheerLocked(id int) int64 {
	var n int64
	for i := range cheers {
		if cheers[i].live && cheers[i].fish == id {
			n += cheers[i].amount
		}
	}
	return n
}

func returnCheers(body *fishBody, rlm realm) {
	for i := range cheers {
		if !cheers[i].live || cheers[i].fish != body.id {
			continue
		}
		amt := cheers[i].amount
		who := cheers[i].who
		cheers[i].live = false
		cheers[i].amount = 0
		send(who, amt, rlm)
	}
}

func bookCheerClaims(atk, vic *fishBody, cheer, now int64) int64 {
	if cheer <= 0 {
		return 0
	}
	var weights []int
	var owners []address
	for i := range cheers {
		if !cheers[i].live || cheers[i].fish != atk.id || cheers[i].amount <= 0 {
			continue
		}
		weights = append(weights, int(cheers[i].amount))
		owners = append(owners, cheers[i].who)
	}
	if len(weights) == 0 {
		return 0
	}
	shares := splitWeights(cheer, weights, owners[0], owners)
	killSeq++
	var placed int64
	for i, share := range shares {
		if share <= 0 {
			continue
		}
		claims = append(claims, claimRow{
			who:     owners[i],
			amount:  share,
			kind:    "cheer",
			killAt:  now,
			killer:  atk.owner,
			victim:  vic.owner,
			killID:  killSeq,
		})
		placed += share
	}
	return placed
}

func bookWatchClaims(atk, vic *fishBody, viewer, now int64) int64 {
	if viewer <= 0 || !anyEligible(atk.owner, vic.owner, now) {
		return 0
	}
	shard := viewer / int64(viewerShards)
	if shard <= 0 {
		return 0
	}
	killSeq++
	var placed int64
	for i := 0; i < viewerShards; i++ {
		claims = append(claims, claimRow{
			amount:  shard,
			kind:    "watch",
			killAt:  now,
			expires: now + viewerWindowMs,
			killer:  atk.owner,
			victim:  vic.owner,
			killID:  killSeq,
		})
		placed += shard
	}
	return placed
}

func anyEligible(killer, victim address, killAt int64) bool {
	for i := range watches {
		if watchEligible(watches[i].who, killAt) && watches[i].who != killer && watches[i].who != victim {
			return true
		}
	}
	return false
}

func watchEligible(who address, killAt int64) bool {
	for i := range watches {
		if watches[i].who == who && watches[i].since <= killAt-viewerWatchMs {
			return true
		}
	}
	return false
}

func watchClaimed(who address, killID int) bool {
	for i := range claims {
		if claims[i].claimed && claims[i].kind == "watch" && claims[i].killID == killID && claims[i].who == who {
			return true
		}
	}
	return false
}

func dropWatch(who address) {
	next := make([]watchRow, 0, len(watches))
	for i := range watches {
		if watches[i].who != who {
			next = append(next, watches[i])
		}
	}
	watches = next
}

func springMilli(now int64) (x, z int, born int64, ok bool) {
	if now < 0 {
		return 0, 0, 0, false
	}
	slot := now / springPeriodMs
	born = slot * springPeriodMs
	if now >= born+springLifeMs {
		return 0, 0, born, false
	}
	angle := math.Mod(float64(slot)*2.399963, 2*math.Pi)
	radius := 48 + (slot*17)%9*22
	x = int(math.Floor(math.Cos(angle)*float64(radius)*1000 + 0.5))
	z = int(math.Floor(math.Sin(angle)*float64(radius)*1000 + 0.5))
	return x, z, born, true
}

func springTouches(sx, sz, springX, springZ int) bool {
	fx, fz := cellMilli(sx, sz)
	dx := int64(fx - springX)
	dz := int64(fz - springZ)
	limit := int64(springRadiusMilli)
	if dx*dx+dz*dz <= limit*limit {
		return true
	}
	ssx := int(math.Floor(float64(springX) / float64(sectorMilli)))
	ssz := int(math.Floor(float64(springZ) / float64(sectorMilli)))
	return sx == ssx && sz == ssz
}

func touchSpring(body *fishBody, now int64) {
	if body == nil || body.burned || body.mustHeal || !body.inMatch || body.pool <= 0 {
		return
	}
	x, z, born, ok := springMilli(now)
	if !ok || body.springBorn == born {
		return
	}
	if !springTouches(body.sx, body.sz, x, z) {
		return
	}
	body.springBorn = born
	gain := body.hp * springHealPercent / 100
	if gain < 1 {
		gain = 1
	}
	body.hpNow += gain
	if body.hpNow > body.hp {
		body.hpNow = body.hp
	}
}

// Package fishlab is a small onyx trial of the corrected kill rule.
// A full copy of shoal/fish did not become live under the deploy deposit.
// This realm does not replace gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/shoal/fish.
// Strike has no size penalty and no prey bonus.
// PayCovered draws 1 whole FISH per 1 whole GNOT of the covered stake.
// The covered stake is the smaller of the two pools. A zero stake pays nothing.
// The draw comes from an approved reserve. It does not mint FISH.
package fishlab

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"

	shoaltoken "gno.land/r/g10ragdr3cjqkael8rslpw4y6rlelhev4h0fswcx/fishcoin"
)

const unit int64 = 1_000_000

var (
	inited  bool
	self    address
	reserve address
	creator address
)

func Init(cur realm, who address) {
	if !cur.IsCurrent() {
		panic("fishlab: realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("fishlab: eoa")
	}
	takeExact(0)
	if inited {
		panic("fishlab: init")
	}
	if !who.IsValid() {
		panic("fishlab: reserve")
	}
	inited = true
	self = cur.Address()
	reserve = who
	creator = cur.Previous().Address()
	chain.Emit("Init", "self", self.String(), "reserve", who.String())
}

func Realm() string {
	return self.String()
}

func Reserve() string {
	return reserve.String()
}

func Strike(bite, hpMax int) int {
	if hpMax < 0 {
		hpMax = 0
	}
	dmg := bite * 100 / (hpMax + 100)
	if dmg < 1 {
		return 1
	}
	return dmg
}

func PayCovered(cur realm, coveredUgnot int64) int64 {
	if !cur.IsCurrent() {
		panic("fishlab: realm")
	}
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("fishlab: eoa")
	}
	takeExact(0)
	if !inited {
		panic("fishlab: init")
	}
	if coveredUgnot <= 0 {
		return 0
	}
	whole := coveredUgnot / unit
	if whole <= 0 {
		return 0
	}
	if shoaltoken.Spender() != self {
		panic("fishlab: spender")
	}
	units := whole * unit
	got := shoaltoken.Draw(cross(cur), reserve, caller.Address(), units)
	chain.Emit("PayCovered", "whole", strconv.FormatInt(whole, 10), "got", strconv.FormatInt(got, 10))
	return got
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("fishlab: payment")
		}
		return
	}
	panic("fishlab: payment")
}

// Package gnotif is a registry of notification triggers. Each trigger names
// a realm and an event type to watch, and the text of the notification that
// gnotif servers send when a matching event lands on chain. A later registry
// version follows the rules in
// https://gnotif.xyz/docs/how-it-works/#rules-for-a-new-registry-version.
package gnotif

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

// Trigger is one declared notification rule. Filter holds comma-separated
// key=value pairs; Title, Body and Link are templates where {key} stands for
// the value of the event's attribute key.
type Trigger struct {
	ID, Target, Event, Filter, Param, Title, Body, Link string
	Declarer                                            address
	Verified                                            bool
}

const (
	targetPrefix   = "gno.land/r/"
	maxTarget      = 256
	maxName        = 64
	maxFilterPairs = 8
	maxBody        = 255
	maxLink        = 256
	maxPerTarget   = 64
)

var (
	triggers avl.Tree // id → *Trigger
	byTarget avl.Tree // target → *avl.Tree of id → *Trigger, verified triggers only
	lastID   seqid.ID
)

// Declare stores a trigger and returns its id. Only the target realm itself
// may declare a trigger for it.
func Declare(cur realm, target, event, filter, param, title, body, link string) string {
	validate(target, event, filter, param, title, body, link)
	caller := cur.Previous()
	verified := caller.IsCode() && caller.PkgPath() == target
	if !verified {
		panic("caller is not the target")
	}
	var own *avl.Tree
	if v := byTarget.Get(target); v != nil {
		own = v.(*avl.Tree)
	}
	if verified && own != nil && own.Size() >= maxPerTarget {
		panic("too many triggers for target")
	}
	tr := &Trigger{
		ID:       lastID.Next().String(),
		Target:   target,
		Event:    event,
		Filter:   filter,
		Param:    param,
		Title:    title,
		Body:     body,
		Link:     link,
		Declarer: caller.Address(),
		Verified: verified,
	}
	triggers.Set(tr.ID, tr)
	if verified {
		if own == nil {
			own = avl.NewTree()
			byTarget.Set(target, own)
		}
		own.Set(tr.ID, tr)
	}
	chain.Emit("TriggerDeclared",
		"id", tr.ID,
		"target", tr.Target,
		"event", tr.Event,
		"filter", tr.Filter,
		"param", tr.Param,
		"title", tr.Title,
		"body", tr.Body,
		"link", tr.Link,
		"declarer", tr.Declarer.String(),
		"verified", strconv.FormatBool(tr.Verified),
	)
	return tr.ID
}

// Remove deletes a trigger. Only its declarer may remove it.
func Remove(cur realm, id string) {
	v := triggers.Get(id)
	if v == nil {
		panic("unknown trigger")
	}
	tr := v.(*Trigger)
	if tr.Declarer != cur.Previous().Address() {
		panic("not the declarer")
	}
	triggers.Remove(id)
	if tr.Verified {
		own := byTarget.Get(tr.Target).(*avl.Tree)
		own.Remove(id)
		if own.Size() == 0 {
			byTarget.Remove(tr.Target)
		}
	}
	chain.Emit("TriggerRemoved", "id", id)
}

func validate(target, event, filter, param, title, body, link string) {
	switch {
	case !validTarget(target):
		panic("invalid target")
	case !validName(event, 1, maxName):
		panic("invalid event")
	case !validFilter(filter):
		panic("invalid filter")
	case !validName(param, 0, maxName):
		panic("invalid param")
	case !sized(title, 1, maxName):
		panic("invalid title")
	case !sized(body, 0, maxBody):
		panic("invalid body")
	case !validLink(link):
		panic("invalid link")
	}
}

func sized(s string, lo, hi int) bool {
	return len(s) >= lo && len(s) <= hi
}

// validTarget accepts a realm path whose segments each match the chain's
// Re_name, so a target names a path where a realm can exist.
func validTarget(target string) bool {
	if !strings.HasPrefix(target, targetPrefix) || len(target) > maxTarget {
		return false
	}
	rest := target[len(targetPrefix):]
	start := 0 // index of the current segment's first byte
	for i := 0; i <= len(rest); i++ {
		if i == len(rest) || rest[i] == '/' {
			if i == start || !isLowerAlnum(rest[i-1]) {
				return false
			}
			start = i + 1
			continue
		}
		c := rest[i]
		switch {
		case i == start:
			if !(c >= 'a' && c <= 'z') {
				return false
			}
		case c == '_' || c == '-':
			if !isLowerAlnum(rest[i-1]) {
				return false
			}
		case !isLowerAlnum(c):
			return false
		}
	}
	return true
}

func isLowerAlnum(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= '0' && c <= '9'
}

// validName accepts identifier bytes only, so a name cannot carry spaces or
// symbols that imitate the verified mark in rendered output.
func validName(s string, lo, hi int) bool {
	if !sized(s, lo, hi) {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_') {
			return false
		}
	}
	return true
}

func validFilter(filter string) bool {
	if filter == "" {
		return true
	}
	pairs := strings.Split(filter, ",")
	if len(pairs) > maxFilterPairs {
		return false
	}
	for _, pair := range pairs {
		key, value, ok := strings.Cut(pair, "=")
		if !ok || !validName(key, 1, maxName) || !sized(value, 1, maxName) || strings.Contains(value, "=") {
			return false
		}
	}
	return true
}

// validLink accepts only a path, so a click always stays on the dapp's origin.
// "//host" starts with a slash yet resolves to another host. A URL parser
// drops tab, LF and CR and reads a backslash as a slash, so "/\t/host" and
// "/\host" would do the same; control bytes and backslashes are refused.
func validLink(link string) bool {
	if !sized(link, 1, maxLink) || !strings.HasPrefix(link, "/") || strings.HasPrefix(link, "//") {
		return false
	}
	for i := 0; i < len(link); i++ {
		if c := link[i]; c < 0x20 || c == 0x7f || c == '\\' {
			return false
		}
	}
	return true
}

package gnotif

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const pageSize = 50

// Render serves "" (the first page), "page/N", "trigger/<id>" and
// "target/<path>".
func Render(path string) string {
	switch {
	case path == "":
		return renderPage(1)
	case strings.HasPrefix(path, "page/"):
		n, err := strconv.Atoi(strings.TrimPrefix(path, "page/"))
		if err != nil || n < 1 {
			return "Not found."
		}
		return renderPage(n)
	case strings.HasPrefix(path, "trigger/"):
		v := triggers.Get(strings.TrimPrefix(path, "trigger/"))
		if v == nil {
			return "Not found."
		}
		return renderTrigger(v.(*Trigger))
	case strings.HasPrefix(path, "target/"):
		own := byTarget.Get(strings.TrimPrefix(path, "target/"))
		if own == nil {
			return "Not found."
		}
		return renderTarget(strings.TrimPrefix(path, "target/"), own.(*avl.Tree))
	}
	return "Not found."
}

// renderPage lists the triggers newest first, pageSize to a page.
func renderPage(n int) string {
	var b strings.Builder
	b.WriteString("# gnotif triggers\n\n")
	pages := (triggers.Size() + pageSize - 1) / pageSize
	if n > pages {
		b.WriteString("No triggers on this page.\n")
		return b.String()
	}
	triggers.ReverseIterateByOffset((n-1)*pageSize, pageSize, func(_ string, v any) bool {
		writeLine(&b, v.(*Trigger))
		return false
	})
	if n < pages {
		b.WriteString("\n[Next page](" + selfPath + ":page/" + strconv.Itoa(n+1) + ")\n")
	}
	return b.String()
}

// renderTarget lists a realm's verified triggers, newest first. The cap on
// them keeps the page to one screen, so it is not paged.
func renderTarget(target string, own *avl.Tree) string {
	var b strings.Builder
	b.WriteString("# gnotif triggers for " + sanitize.InlineText(target) + "\n\n")
	own.ReverseIterate("", "", func(_ string, v any) bool {
		writeLine(&b, v.(*Trigger))
		return false
	})
	b.WriteString("\n[All triggers](" + selfPath + ")\n")
	return b.String()
}

func writeLine(b *strings.Builder, tr *Trigger) {
	b.WriteString("- [**" + tr.ID + "**](" + selfPath + ":trigger/" + tr.ID + ") " +
		sanitize.InlineText(tr.Target) + " · " + sanitize.InlineText(tr.Event))
	if tr.Param != "" {
		b.WriteString(" · param " + sanitize.InlineText(tr.Param))
	}
	if tr.Verified {
		b.WriteString(" · ✓ verified")
	}
	b.WriteString(" · by " + tr.Declarer.String() + "\n")
}

func renderTrigger(tr *Trigger) string {
	var b strings.Builder
	b.WriteString("# Trigger " + tr.ID + "\n\n")
	b.WriteString("- Target: " + sanitize.InlineText(tr.Target) + "\n")
	b.WriteString("- Event: " + sanitize.InlineText(tr.Event) + "\n")
	b.WriteString("- Filter: " + sanitize.InlineText(tr.Filter) + "\n")
	b.WriteString("- Param: " + sanitize.InlineText(tr.Param) + "\n")
	b.WriteString("- Title: " + sanitize.InlineText(tr.Title) + "\n")
	b.WriteString("- Body: " + sanitize.InlineText(tr.Body) + "\n")
	b.WriteString("- Link: " + sanitize.InlineText(tr.Link) + "\n")
	b.WriteString("- Declarer: " + tr.Declarer.String() + "\n")
	if tr.Verified {
		b.WriteString("- ✓ verified\n")
	}
	b.WriteString("\n[All triggers](" + selfPath + ")\n")
	return b.String()
}

// selfPath is this realm's path on gnoweb. It is read at package init, where
// the realm itself is current; Render is not crossing, so reading it there
// would give the caller's path. It only builds links.
var selfPath = strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), "gno.land")

// Package echo is gnotif's demo realm: Echo sends a message back to its
// caller as a browser notification.
package echo

import (
	"chain"

	"gno.land/r/g18me5p9kqqxyswd8ytrmlv3q8kvy7uacx2v90ne/gnotif/v0"
)

// The registry sees this realm as the caller, so the trigger is verified.
func init(cur realm) {
	gnotif.Declare(cross(cur), cur.PkgPath(), "Echo", "", "to", "Echo", "{msg}", "/")
}

// Echo sends msg to the browsers that opted in with the caller's address.
// The recipient is always the caller, so nobody can notify another address.
func Echo(cur realm, msg string) {
	chain.Emit("Echo", "to", cur.Previous().Address().String(), "msg", msg)
}

// Render serves one page for every path: what Echo does and where to try it.
func Render(_ string) string {
	return "# Echo\n\n" +
		"Call `Echo` with a message, and gnotif shows it as a notification in the browsers " +
		"that turned on notifications for your own address. Nobody else can send one to you.\n\n" +
		"Try it on [demo.gnotif.xyz](https://demo.gnotif.xyz).\n"
}

