	for _, pair := range pairs {
		key, value, ok := strings.Cut(pair, "=")
		if !ok || !validName(key, 1, maxName) || !sized(value, 1, maxName) || strings.Contains(value, "=") {
			return false
		}
	}
	return true
}

// validLink accepts only a path, so a click always stays on the dapp's origin.
// "//host" starts with a slash yet resolves to another host. A URL parser
// drops tab, LF and CR and reads a backslash as a slash, so "/\t/host" and
// "/\host" would do the same; control bytes and backslashes are refused.
func validLink(link string) bool {
	if !sized(link, 1, maxLink) || !strings.HasPrefix(link, "/") || strings.HasPrefix(link, "//") {
		return false
	}
	for i := 0; i < len(link); i++ {
		if c := link[i]; c < 0x20 || c == 0x7f || c == '\\' {
			return false
		}
	}
	return true
}

package gnotif

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const pageSize = 50

// Render serves "" (the first page), "page/N", "trigger/<id>" and
// "target/<path>".
func Render(path string) string {
	switch {
	case path == "":
		return renderPage(1)
	case strings.HasPrefix(path, "page/"):
		n, err := strconv.Atoi(strings.TrimPrefix(path, "page/"))
		if err != nil || n < 1 {
			return "Not found."
		}
		return renderPage(n)
	case strings.HasPrefix(path, "trigger/"):
		v := triggers.Get(strings.TrimPrefix(path, "trigger/"))
		if v == nil {
			return "Not found."
		}
		return renderTrigger(v.(*Trigger))
	case strings.HasPrefix(path, "target/"):
		own := byTarget.Get(strings.TrimPrefix(path, "target/"))
		if own == nil {
			return "Not found."
		}
		return renderTarget(strings.TrimPrefix(path, "target/"), own.(*avl.Tree))
	}
	return "Not found."
}

// renderPage lists the triggers newest first, pageSize to a page.
func renderPage(n int) string {
	var b strings.Builder
	b.WriteString("# gnotif triggers\n\n")
	pages := (triggers.Size() + pageSize - 1) / pageSize
	if n > pages {
		b.WriteString("No triggers on this page.\n")
		return b.String()
	}
	triggers.ReverseIterateByOffset((n-1)*pageSize, pageSize, func(_ string, v any) bool {
		writeLine(&b, v.(*Trigger))
		return false
	})
	if n < pages {
		b.WriteString("\n[Next page](" + selfPath + ":page/" + strconv.Itoa(n+1) + ")\n")
	}
	return b.String()
}

// renderTarget lists a realm's verified triggers, newest first. The cap on
// them keeps the page to one screen, so it is not paged.
func renderTarget(target string, own *avl.Tree) string {
	var b strings.Builder
	b.WriteString("# gnotif triggers for " + sanitize.InlineText(target) + "\n\n")
	own.ReverseIterate("", "", func(_ string, v any) bool {
		writeLine(&b, v.(*Trigger))
		return false
	})
	b.WriteString("\n[All triggers](" + selfPath + ")\n")
	return b.String()
}

func writeLine(b *strings.Builder, tr *Trigger) {
	b.WriteString("- [**" + tr.ID + "**](" + selfPath + ":trigger/" + tr.ID + ") " +
		sanitize.InlineText(tr.Target) + " · " + sanitize.InlineText(tr.Event))
	if tr.Param != "" {
		b.WriteString(" · param " + sanitize.InlineText(tr.Param))
	}
	if tr.Verified {
		b.WriteString(" · ✓ verified")
	}
	b.WriteString(" · by " + tr.Declarer.String() + "\n")
}

func renderTrigger(tr *Trigger) string {
	var b strings.Builder
	b.WriteString("# Trigger " + tr.ID + "\n\n")
	b.WriteString("- Target: " + sanitize.InlineText(tr.Target) + "\n")
	b.WriteString("- Event: " + sanitize.InlineText(tr.Event) + "\n")
	b.WriteString("- Filter: " + sanitize.InlineText(tr.Filter) + "\n")
	b.WriteString("- Param: " + sanitize.InlineText(tr.Param) + "\n")
	b.WriteString("- Title: " + sanitize.InlineText(tr.Title) + "\n")
	b.WriteString("- Body: " + sanitize.InlineText(tr.Body) + "\n")
	b.WriteString("- Link: " + sanitize.InlineText(tr.Link) + "\n")
	b.WriteString("- Declarer: " + tr.Declarer.String() + "\n")
	if tr.Verified {
		b.WriteString("- ✓ verified\n")
	}
	b.WriteString("\n[All triggers](" + selfPath + ")\n")
	return b.String()
}

// selfPath is this realm's path on gnoweb. It is read at package init, where
// the realm itself is current; Render is not crossing, so reading it there
// would give the caller's path. It only builds links.
var selfPath = strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), "gno.land")

// Package echo is gnotif's demo realm: Echo sends a message back to its
// caller as a browser notification.
package echo

import (
	"chain"

	"gno.land/r/nym-gfanton001/gnotif/v0"
)

// The registry sees this realm as the caller, so the trigger is verified.
func init(cur realm) {
	gnotif.Declare(cross(cur), cur.PkgPath(), "Echo", "", "to", "Echo", "{msg}", "/")
}

// Echo sends msg to the browsers that opted in with the caller's address.
// The recipient is always the caller, so nobody can notify another address.
func Echo(cur realm, msg string) {
	chain.Emit("Echo", "to", cur.Previous().Address().String(), "msg", msg)
}

// Render serves one page for every path: what Echo does and where to try it.
func Render(_ string) string {
	return "# Echo\n\n" +
		"Call `Echo` with a message, and gnotif shows it as a notification in the browsers " +
		"that turned on notifications for your own address. Nobody else can send one to you.\n\n" +
		"Try it on [demo.gnotif.xyz](https://demo.gnotif.xyz).\n"
}

// Package fishmark is a second trial FISH ledger for the fishbay realm.
// Init mints a fixed supply and no later call can mint. Wallet transfers are not taxed.
// The symbol is FISH. TokenID is the chain identity, because fishcoin and the NFT
// collection use the same letters. SetSpender can be called only after Init, and only once.
// Point it at fishbay after that realm's Realm() is known. Do not point it at shoal/fish.
package fishmark

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ownable/v0"
)

const (
	unit            int64 = 1_000_000
	supplyWhole     int64 = 100_000_000
	seasonWhole     int64 = 43_000_000
	liquidityWhole  int64 = 20_000_000
	ecosystemWhole  int64 = 15_000_000
	communityWhole  int64 = 12_000_000
	teamWhole       int64 = 10_000_000
	maxBuyTaxBps    int64 = 500
	maxSellTaxBps   int64 = 1000
	defaultBuyTax   int64 = 200
	defaultSellTax  int64 = 400
)

var (
	token     *grc20.Token
	ledger    *grc20.PrivateLedger
	admin     *ownable.Ownable
	inited     bool
	sealed     bool
	spender    address
	spenderSet bool
	buyTaxBps  int64 = defaultBuyTax
	sellTaxBps int64 = defaultSellTax
)

// Init mints the fixed supply once and seals the ledger. The five treasuries must be distinct.
func Init(cur realm, season, liquidity, ecosystem, community, team address) {
	if !cur.IsCurrent() {
		panic("fishmark: realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("fishmark: eoa")
	}
	takeExact(0)
	if inited {
		panic("fishmark: init")
	}
	if !distinct(season, liquidity, ecosystem, community, team) {
		panic("fishmark: addr")
	}
	tok, led := grc20.NewToken("Fishmark", "FISH", 6, 0, cur)
	credit(led, season, seasonWhole*unit)
	credit(led, liquidity, liquidityWhole*unit)
	credit(led, ecosystem, ecosystemWhole*unit)
	credit(led, community, communityWhole*unit)
	credit(led, team, teamWhole*unit)
	if tok.TotalSupply() != supplyWhole*unit {
		panic("fishmark: supply")
	}
	token = tok
	ledger = led
	admin = ownable.NewWithAddress(cur.Previous().Address())
	inited = true
	sealed = true
	chain.Emit(
		"Init",
		"token", tok.ID(),
		"admin", cur.Previous().Address().String(),
		"supply", strconv.FormatInt(supplyWhole*unit, 10),
	)
}

// Transfer moves FISH from the caller to to. The amount is not taxed.
func Transfer(cur realm, to address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().Transfer(0, cur, to, amount))
	chain.Emit("Send", "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// Approve lets spender move up to amount from the caller. This replaces the previous allowance.
func Approve(cur realm, spender address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().Approve(0, cur, spender, amount))
	chain.Emit("Approve", "spender", spender.String(), "amount", strconv.FormatInt(amount, 10))
}

// TransferFrom moves amount from owner to to, using the caller's allowance. The amount is not taxed.
func TransferFrom(cur realm, owner, to address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().TransferFrom(0, cur, owner, to, amount))
	chain.Emit("SendFrom", "owner", owner.String(), "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// SetBuyTaxBps stores the buy tax for a later pool. The cap is 500 bps. This does not tax wallets.
func SetBuyTaxBps(cur realm, next int64) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	if !admin.OwnedBy(caller) {
		panic("fishmark: admin")
	}
	if next < 0 || next > maxBuyTaxBps {
		panic("fishmark: tax")
	}
	buyTaxBps = next
	chain.Emit("SetBuyTaxBps", "bps", strconv.FormatInt(next, 10))
}

// SetSellTaxBps stores the sell tax for a later pool. The cap is 1000 bps. This does not tax wallets.
func SetSellTaxBps(cur realm, next int64) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	if !admin.OwnedBy(caller) {
		panic("fishmark: admin")
	}
	if next < 0 || next > maxSellTaxBps {
		panic("fishmark: tax")
	}
	sellTaxBps = next
	chain.Emit("SetSellTaxBps", "bps", strconv.FormatInt(next, 10))
}

// TransferAdmin hands the tax hook to next. Balances stay where they are.
func TransferAdmin(cur realm, next address) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	if !next.IsValid() {
		panic("fishmark: admin")
	}
	if err := admin.TransferOwnership(0, cur, next); err != nil {
		panic("fishmark: admin")
	}
	chain.Emit("TransferAdmin", "next", next.String())
}

func Name() string {
	requireReady()
	return token.GetName()
}

func Symbol() string {
	requireReady()
	return token.GetSymbol()
}

func Decimals() int {
	requireReady()
	return token.GetDecimals()
}

func TotalSupply() int64 {
	requireReady()
	return token.TotalSupply()
}

func BalanceOf(who address) int64 {
	requireReady()
	return token.BalanceOf(who)
}

func Allowance(owner, spender address) int64 {
	requireReady()
	return token.Allowance(owner, spender)
}

func TokenID() string {
	requireReady()
	return token.ID()
}

func BuyTaxBps() int64  { return buyTaxBps }
func SellTaxBps() int64 { return sellTaxBps }
func Version() string   { return "fishmark-1" }
func Sealed() bool      { return sealed }

// Spender is the one realm allowed to Draw. It is empty until SetSpender.
func Spender() address { return spender }

// SetSpender records the fish realm once. A later call cannot replace it.
func SetSpender(cur realm, who address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	if !admin.OwnedBy(caller) {
		panic("fishmark: admin")
	}
	if spenderSet || !who.IsValid() {
		panic("fishmark: spender")
	}
	spender = who
	spenderSet = true
	chain.Emit("SetSpender", "who", who.String())
}

// Draw moves min(amount, balance, allowance) from owner to to.
// Only the recorded spender may call it. The owner must have approved that spender.
// A short balance or allowance moves nothing and does not panic. This does not mint.
func Draw(cur realm, owner, to address, amount int64) int64 {
	if !cur.IsCurrent() {
		panic("fishmark: realm")
	}
	if !spenderSet || cur.Previous().Address() != spender {
		panic("fishmark: spender")
	}
	takeExact(0)
	requireReady()
	if amount <= 0 || !owner.IsValid() || !to.IsValid() {
		return 0
	}
	bal := token.BalanceOf(owner)
	if amount > bal {
		amount = bal
	}
	allow := token.Allowance(owner, spender)
	if amount > allow {
		amount = allow
	}
	if amount <= 0 {
		return 0
	}
	must(ledger.CallerTeller().TransferFrom(0, cur, owner, to, amount))
	chain.Emit("Draw", "owner", owner.String(), "to", to.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

func Admin() address {
	if admin == nil {
		return address("")
	}
	return admin.Owner()
}

func Render(path string) string {
	if path != "" {
		return "# Fishmark\n\nUnknown path.\n"
	}
	return "# Fishmark\n\nFixed supply. Wallet transfers are not taxed.\n\nThis ledger is for fishbay. TokenID is the chain identity.\n"
}

func credit(led *grc20.PrivateLedger, who address, amount int64) {
	if err := led.Mint(who, amount); err != nil {
		panic(err)
	}
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func requireReady() {
	if !inited || !sealed || token == nil || ledger == nil || admin == nil {
		panic("fishmark: init")
	}
}

func requireUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("fishmark: eoa")
	}
	return cur.Previous().Address()
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("fishmark: payment")
		}
		return
	}
	panic("fishmark: payment")
}

func distinct(xs ...address) bool {
	for i, a := range xs {
		if !a.IsValid() {
			return false
		}
		for j := 0; j < i; j++ {
			if xs[j] == a {
				return false
			}
		}
	}
	return true
}

// Package fishbay is a small onyx trial sea.
// It keeps Mint, Register, Leave, and Bite.
// Damage is floor(bite * 100 / (hpMax + 100)), at least 1.
// A kill pays GNOT and FISH from the smaller stake.
// FISH is drawn from fishmark. This realm does not mint FISH.
// Lay, the market, cheer, and party are not in this bay.
// shoal/fish stays the live NFT collection. This package is not that collection.
// The trial mint is 1 GNOT and the stake floor is 1 GNOT.
package fishbay

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"

	fishmark "gno.land/r/g10ragdr3cjqkael8rslpw4y6rlelhev4h0fswcx/fishmark"
)

const (
	denom    = "ugnot"
	unit     int64 = 1_000_000
	mintFee  int64 = 1_000_000
	stakeMin int64 = 1_000_000
	biteStat       = 69
	hpStat         = 88
	seatMax        = 16
)

type swimmer struct {
	owner    address
	name     string
	pool     int64
	hp       int
	hpMax    int
	bite     int
	inSea    bool
	mustHeal bool
}

var (
	inited  bool
	self    address
	reserve address
	upgrade address
	lpSink  address
	team    address
	burn    address
	minted  int
	roster  [seatMax + 1]swimmer
)

// Init records the FISH reserve and the four GNOT sinks. The reserve must not also be a sink.
// Upgrade and burn may be the same address. Call this once, from an EOA, with no coins.
func Init(cur realm, who, up, lp, crew, ash address) {
	if !cur.IsCurrent() {
		panic("fishbay: realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("fishbay: eoa")
	}
	takeExact(0)
	if inited {
		panic("fishbay: init")
	}
	if !who.IsValid() || !up.IsValid() || !lp.IsValid() || !crew.IsValid() || !ash.IsValid() {
		panic("fishbay: addr")
	}
	if who == up || who == lp || who == crew || who == ash || lp == crew {
		panic("fishbay: addr")
	}
	inited = true
	self = cur.Address()
	reserve = who
	upgrade = up
	lpSink = lp
	team = crew
	burn = ash
	chain.Emit("Init", "self", self.String(), "reserve", who.String())
}

// Mint sells one trial fish for 1 GNOT. The fee leaves this realm in the same call.
func Mint(cur realm, name string) int {
	if !cur.IsCurrent() {
		panic("fishbay: realm")
	}
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("fishbay: eoa")
	}
	requireInit()
	takeExact(mintFee)
	if minted >= seatMax || !validName(name) {
		panic("fishbay: mint")
	}
	minted++
	roster[minted] = swimmer{
		owner: caller.Address(),
		name:  name,
		hp:    hpStat,
		hpMax: hpStat,
		bite:  biteStat,
	}
	payMint(mintFee, cur)
	chain.Emit("Mint", "id", strconv.Itoa(minted), "owner", caller.Address().String())
	return minted
}

// Register seats a fish. The attached coins are the stake and must be at least 1 GNOT.
func Register(cur realm, id int, stake int64) {
	if !cur.IsCurrent() {
		panic("fishbay: realm")
	}
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("fishbay: eoa")
	}
	requireInit()
	if stake < stakeMin {
		panic("fishbay: stake")
	}
	takeExact(stake)
	fish := mustFish(id)
	if fish.owner != caller.Address() || fish.inSea || fish.mustHeal || fish.hp*100 < fish.hpMax*30 {
		panic("fishbay: register")
	}
	if ownerSeated(caller.Address()) {
		panic("fishbay: seat")
	}
	fish.pool = stake
	fish.inSea = true
	chain.Emit("Register", "id", strconv.Itoa(id), "stake", strconv.FormatInt(stake, 10))
}

// Leave returns the seated stake to the owner. A fish that is already out of the bay cannot leave.
func Leave(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("fishbay: realm")
	}
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("fishbay: eoa")
	}
	requireInit()
	takeExact(0)
	fish := mustFish(id)
	if fish.owner != caller.Address() || !fish.inSea {
		panic("fishbay: leave")
	}
	stake := fish.pool
	fish.pool = 0
	fish.inSea = false
	send(fish.owner, stake, cur)
	chain.Emit("Leave", "id", strconv.Itoa(id), "stake", strconv.FormatInt(stake, 10))
}

// Bite deals flat damage. A kill pays the smaller stake and draws 1 FISH per 1 GNOT of that stake.
func Bite(cur realm, id, target int) int {
	if !cur.IsCurrent() {
		panic("fishbay: realm")
	}
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("fishbay: eoa")
	}
	requireInit()
	takeExact(0)
	if id == target {
		panic("fishbay: bite")
	}
	atk := mustFish(id)
	vic := mustFish(target)
	if atk.owner != caller.Address() || !atk.inSea || !vic.inSea || atk.owner == vic.owner || atk.pool < stakeMin || vic.pool < stakeMin {
		panic("fishbay: bite")
	}
	dmg := Strike(atk.bite, vic.hpMax)
	if vic.hp > dmg {
		vic.hp -= dmg
		chain.Emit("Bite", "id", strconv.Itoa(id), "target", strconv.Itoa(target), "dmg", strconv.Itoa(dmg))
		return dmg
	}
	covered := atk.pool
	if vic.pool < covered {
		covered = vic.pool
	}
	excess := vic.pool - covered
	owner := vic.owner
	vic.hp = downHP(vic.hpMax)
	vic.pool = 0
	vic.inSea = false
	vic.mustHeal = true
	killer, lp, crew, buyback := splitKill(covered)
	send(atk.owner, killer, cur)
	send(lpSink, lp, cur)
	send(team, crew, cur)
	send(burn, buyback, cur)
	send(owner, excess, cur)
	got := payFish(cur, atk.owner, covered)
	chain.Emit(
		"Kill",
		"id", strconv.Itoa(id),
		"target", strconv.Itoa(target),
		"covered", strconv.FormatInt(covered, 10),
		"fish", strconv.FormatInt(got, 10),
	)
	return dmg
}

// Strike is the damage formula. Size and rarity are not inputs.
func Strike(bite, hpMax int) int {
	if bite < 1 {
		bite = 1
	}
	if hpMax < 0 {
		hpMax = 0
	}
	dmg := bite * 100 / (hpMax + 100)
	if dmg < 1 {
		return 1
	}
	return dmg
}

func Realm() address { return self }
func Reserve() address { return reserve }
func Version() string { return "fishbay-1" }
func MintPrice() int64 { return mintFee }
func StakeMin() int64 { return stakeMin }
func Minted() int { return minted }

func OwnerOf(id int) address { return mustFish(id).owner }
func PoolOf(id int) int64    { return mustFish(id).pool }
func HpOf(id int) int        { return mustFish(id).hp }
func InSea(id int) bool      { return mustFish(id).inSea }
func MustHeal(id int) bool   { return mustFish(id).mustHeal }

func Render(path string) string {
	if path != "" {
		return "# Fishbay\n\nUnknown path.\n"
	}
	return "# Fishbay\n\nTrial bay. Mint, Register, Leave, and Bite. This is not the shoal/fish collection.\n"
}

func payFish(cur realm, to address, covered int64) int64 {
	whole := covered / unit
	if whole <= 0 {
		return 0
	}
	return fishmark.Draw(cross(cur), reserve, to, whole*unit)
}

func splitKill(covered int64) (killer, lp, crew, buyback int64) {
	killer = covered * 80 / 100
	lp = covered * 10 / 100
	teamPart := covered * 3 / 100
	buyback = covered * 3 / 100
	cheer := covered * 4 / 100
	buyback += covered - killer - lp - teamPart - buyback - cheer
	crew = teamPart + cheer
	return
}

func payMint(fee int64, rlm realm) {
	up := fee * 6000 / 10000
	lp := fee * 2000 / 10000
	crew := fee * 1000 / 10000
	ash := fee - up - lp - crew
	send(upgrade, up, rlm)
	send(lpSink, lp, rlm)
	send(team, crew, rlm)
	send(burn, ash, rlm)
}

func send(to address, amt int64, rlm realm) {
	if !rlm.IsCurrent() {
		panic("fishbay: realm")
	}
	if amt == 0 {
		return
	}
	if !to.IsValid() {
		panic("fishbay: sink")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: denom, Amount: amt}})
}

func mustFish(id int) *swimmer {
	requireInit()
	if id < 1 || id > minted {
		panic("fishbay: fish")
	}
	return &roster[id]
}

func ownerSeated(who address) bool {
	for i := 1; i <= minted; i++ {
		if roster[i].owner == who && roster[i].inSea {
			return true
		}
	}
	return false
}

func downHP(hpMax int) int {
	hp := hpMax * 30 / 100
	if hp < 1 {
		return 1
	}
	return hp
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > 16 {
		return false
	}
	for _, c := range name {
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') {
			return false
		}
	}
	return true
}

func requireInit() {
	if !inited || self == address("") {
		panic("fishbay: init")
	}
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("fishbay: payment")
		}
		return
	}
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount != n {
		panic("fishbay: payment")
	}
}

// Package fishduel is a two-person trial.
// Swim stays off chain. Settle pays one covered stake from three sealed samples.
// Each player binds an ed25519 mark key at Register. The realm cannot check a loose
// secp256k1 wallet signature. There is no machine fish and no FISH draw.
// shoal/fish stays the live collection. Mint is 1 GNOT and the stake floor is 1 GNOT.
// A sample note is bout:seq:height:id:x:z:time:secret:sig
// The mark signs the sha256 of bout,seq,height,id,x,z,time,secret joined by commas.
// secret is 32 lowercase hex chars. sig is 128 lowercase hex chars. The public key is 64.
package fishduel

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
	"time"
)

const (
	denom          = "ugnot"
	unit     int64 = 1_000_000
	mintFee  int64 = 1_000_000
	stakeMin int64 = 1_000_000
	biteStat       = 69
	hpStat         = 88
	reach          = 2
	hitGap   int64 = 2_400
	cellMs   int64 = 320
	quietMs  int64 = 60_000
	seatMax        = 8
	box            = 32
	stepCap        = 16
	packMax        = 2_400
)

type swimmer struct {
	owner   address
	name    string
	pool    int64
	hp      int
	inSea   bool
	ended   bool
	markSet bool
	mark    [32]byte
}

type note struct {
	bout   int
	seq    int
	height int64
	id     int
	x      int
	z      int
	at     int64
	secret string
	sig    string
}

var (
	inited     bool
	self       address
	lpSink     address
	team       address
	burn       address
	minted     int
	openBout   int
	boutOpen   bool
	seatMilli  int64
	seatHeight int64
	roster     [seatMax + 1]swimmer
)

// Init records three GNOT sinks. They must be distinct. Call once, from an EOA, with no coins.
// The mint fee is 60/20/10 and the last tenth joins team. Kill cheer also joins team.
func Init(cur realm, lp, crew, ash address) {
	if !cur.Previous().IsUserCall() {
		panic("fishduel: eoa")
	}
	takeExact(0)
	if inited {
		panic("fishduel: init")
	}
	if !lp.IsValid() || !crew.IsValid() || !ash.IsValid() || lp == crew || lp == ash || crew == ash {
		panic("fishduel: addr")
	}
	inited = true
	self = cur.Address()
	lpSink = lp
	team = crew
	burn = ash
	chain.Emit("Init", "self", self.String())
}

// Mint sells one trial fish for 1 GNOT. The fee leaves this realm in the same call.
func Mint(cur realm, name string) int {
	caller := gate(cur, mintFee)
	if minted >= seatMax || !validName(name) {
		panic("fishduel: mint")
	}
	minted++
	roster[minted] = swimmer{owner: caller, name: name, hp: hpStat}
	payMint(mintFee, cur)
	chain.Emit("Mint", "id", strconv.Itoa(minted), "owner", caller.String())
	return minted
}

// Register seats a fish and binds its mark key. The attached coins are the stake.
func Register(cur realm, id int, stake int64, pub string) {
	caller := gate(cur, stake)
	if stake < stakeMin {
		panic("fishduel: stake")
	}
	fish := mustFish(id)
	if fish.owner != caller || fish.inSea || fish.ended || fish.markSet || seated(caller) || seatedCount() >= 2 {
		panic("fishduel: register")
	}
	raw := mustHex(pub, 32)
	for i := 0; i < 32; i++ {
		fish.mark[i] = raw[i]
	}
	fish.markSet = true
	fish.pool = stake
	fish.inSea = true
	if seatedCount() == 2 {
		openBout++
		boutOpen = true
		seatMilli = time.Now().UnixMilli()
		seatHeight = runtime.ChainHeight()
	}
	chain.Emit("Register", "id", strconv.Itoa(id), "bout", strconv.Itoa(openBout))
}

// Leave returns the seated stake. While the other fish is seated, Leave waits 60 seconds.
func Leave(cur realm, id int) {
	caller := gate(cur, 0)
	fish := mustFish(id)
	if fish.owner != caller || !fish.inSea {
		panic("fishduel: leave")
	}
	if otherSeated(id) && time.Now().UnixMilli() < seatMilli+quietMs {
		panic("fishduel: leave")
	}
	if otherSeated(id) {
		boutOpen = false
	}
	stake := fish.pool
	fish.pool = 0
	fish.inSea = false
	send(fish.owner, stake, cur)
	chain.Emit("Leave", "id", strconv.Itoa(id), "stake", strconv.FormatInt(stake, 10))
}

// Settle pays a kill from six notes, killer then victim, three samples, separated by slashes.
func Settle(cur realm, id, target int, pack string) {
	caller := gate(cur, 0)
	if !boutOpen || id == target || len(pack) == 0 || len(pack) > packMax {
		panic("fishduel: settle")
	}
	atk := mustFish(id)
	vic := mustFish(target)
	if atk.owner != caller || !atk.inSea || !vic.inSea || atk.owner == vic.owner || atk.pool < stakeMin || vic.pool < stakeMin {
		panic("fishduel: settle")
	}
	notes := strings.Split(pack, "/")
	if len(notes) != 6 {
		panic("fishduel: note")
	}
	var got [3][2]note
	for i := 0; i < 6; i++ {
		got[i/2][i%2] = parseNote(notes[i])
	}
	checkNotes(id, target, got)
	covered := atk.pool
	if vic.pool < covered {
		covered = vic.pool
	}
	excess := vic.pool - covered
	owner := vic.owner
	vic.hp = 0
	vic.pool = 0
	vic.inSea = false
	vic.ended = true
	boutOpen = false
	killer, lp, crew, buyback := splitKill(covered)
	send(atk.owner, killer, cur)
	send(lpSink, lp, cur)
	send(team, crew, cur)
	send(burn, buyback, cur)
	send(owner, excess, cur)
	chain.Emit("Kill", "id", strconv.Itoa(id), "target", strconv.Itoa(target), "covered", strconv.FormatInt(covered, 10))
}

// Strike is floor(bite * 100 / (hpMax + 100)), at least 1.
func Strike(bite, hpMax int) int {
	if bite < 1 {
		bite = 1
	}
	if hpMax < 0 {
		hpMax = 0
	}
	dmg := bite * 100 / (hpMax + 100)
	if dmg < 1 {
		return 1
	}
	return dmg
}

func Realm() address         { return self }
func Version() string        { return "fishduel-1" }
func MintPrice() int64       { return mintFee }
func StakeMin() int64        { return stakeMin }
func Minted() int            { return minted }
func Bout() int              { return openBout }
func BoutOpen() bool         { return boutOpen }
func SeatHeight() int64      { return seatHeight }
func Height() int64          { return runtime.ChainHeight() }
func Now() int64             { return time.Now().UnixMilli() }
func OwnerOf(id int) address { return mustFish(id).owner }
func PoolOf(id int) int64    { return mustFish(id).pool }
func HpOf(id int) int        { return mustFish(id).hp }
func InSea(id int) bool      { return mustFish(id).inSea }
func Ended(id int) bool      { return mustFish(id).ended }

func MarkOf(id int) string {
	fish := mustFish(id)
	if !fish.markSet {
		return ""
	}
	return hex.EncodeToString(fish.mark[:])
}

func Render(path string) string {
	if path != "" {
		return "# Fishduel\n\nUnknown path.\n"
	}
	return "# Fishduel\n\nTwo-person trial. Mint, Register, Settle, and Leave. This is not the shoal/fish collection.\n"
}

func gate(cur realm, pay int64) address {
	if !cur.Previous().IsUserCall() {
		panic("fishduel: eoa")
	}
	requireInit()
	takeExact(pay)
	return cur.Previous().Address()
}

func checkNotes(id, target int, got [3][2]note) {
	hp := hpStat
	var prevH int64
	var prevT int64
	var ax, az, bx, bz int
	for i := 0; i < 3; i++ {
		a := got[i][0]
		b := got[i][1]
		if a.bout != openBout || b.bout != openBout || a.seq != i+1 || b.seq != i+1 {
			panic("fishduel: sample")
		}
		if a.height != b.height || a.height < seatHeight || a.height > runtime.ChainHeight() {
			panic("fishduel: sample")
		}
		if i > 0 && (a.height <= prevH || a.at-prevT < hitGap) {
			panic("fishduel: sample")
		}
		if a.id != id || b.id != target || !inBox(a.x, a.z) || !inBox(b.x, b.z) {
			panic("fishduel: sample")
		}
		if gap(a.x, a.z, b.x, b.z) > reach {
			panic("fishduel: range")
		}
		if i > 0 && (gap(ax, az, a.x, a.z) > stepMax(a.at-prevT) || gap(bx, bz, b.x, b.z) > stepMax(a.at-prevT)) {
			panic("fishduel: step")
		}
		if !signed(id, a) || !signed(target, b) {
			panic("fishduel: sig")
		}
		dmg := Strike(biteStat, hpStat)
		if i < 2 {
			if hp <= dmg {
				panic("fishduel: hp")
			}
			hp -= dmg
		} else if hp > dmg || a.at > time.Now().UnixMilli() {
			panic("fishduel: hp")
		}
		prevH = a.height
		prevT = a.at
		ax, az, bx, bz = a.x, a.z, b.x, b.z
	}
}

func signed(id int, n note) bool {
	fish := mustFish(id)
	if !fish.markSet || n.id != id {
		return false
	}
	sum := sha256.Sum256([]byte(canon(n)))
	sig := mustHex(n.sig, 64)
	return ed25519.Verify(fish.mark[:], sum[:], sig)
}

func canon(n note) string {
	return strconv.Itoa(n.bout) + "," + strconv.Itoa(n.seq) + "," + strconv.FormatInt(n.height, 10) + "," + strconv.Itoa(n.id) + "," + strconv.Itoa(n.x) + "," + strconv.Itoa(n.z) + "," + strconv.FormatInt(n.at, 10) + "," + n.secret
}

func parseNote(raw string) note {
	p := strings.Split(raw, ":")
	if len(p) != 9 || len(p[7]) != 32 || len(p[8]) != 128 {
		panic("fishduel: note")
	}
	return note{atoi(p[0]), atoi(p[1]), atoi64(p[2]), atoi(p[3]), atoi(p[4]), atoi(p[5]), atoi64(p[6]), p[7], p[8]}
}

func stepMax(dt int64) int {
	n := int(dt / cellMs)
	if n < 1 {
		return 1
	}
	if n > stepCap {
		return stepCap
	}
	return n
}

func gap(ax, az, bx, bz int) int {
	dx := ax - bx
	if dx < 0 {
		dx = -dx
	}
	dz := az - bz
	if dz < 0 {
		dz = -dz
	}
	if dx > dz {
		return dx
	}
	return dz
}

func inBox(x, z int) bool {
	return x >= -box && x <= box && z >= -box && z <= box
}

func splitKill(covered int64) (killer, lp, crew, buyback int64) {
	killer = covered * 80 / 100
	lp = covered * 10 / 100
	teamPart := covered * 3 / 100
	buyback = covered * 3 / 100
	cheer := covered * 4 / 100
	buyback += covered - killer - lp - teamPart - buyback - cheer
	crew = teamPart + cheer
	return
}

func payMint(fee int64, rlm realm) {
	lp := fee * 6000 / 10000
	crew := fee * 2000 / 10000
	ash := fee * 1000 / 10000
	send(lpSink, lp, rlm)
	send(team, crew+fee-lp-crew-ash, rlm)
	send(burn, ash, rlm)
}

func send(to address, amt int64, rlm realm) {
	if !rlm.IsCurrent() {
		panic("fishduel: realm")
	}
	if amt == 0 {
		return
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: denom, Amount: amt}})
}

func mustFish(id int) *swimmer {
	requireInit()
	if id < 1 || id > minted {
		panic("fishduel: fish")
	}
	return &roster[id]
}

func seated(who address) bool {
	for i := 1; i <= minted; i++ {
		if roster[i].owner == who && roster[i].inSea {
			return true
		}
	}
	return false
}

func seatedCount() int {
	n := 0
	for i := 1; i <= minted; i++ {
		if roster[i].inSea {
			n++
		}
	}
	return n
}

func otherSeated(id int) bool {
	for i := 1; i <= minted; i++ {
		if i != id && roster[i].inSea {
			return true
		}
	}
	return false
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > 16 {
		return false
	}
	for _, c := range name {
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') {
			return false
		}
	}
	return true
}

func requireInit() {
	if !inited || self == address("") {
		panic("fishduel: init")
	}
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("fishduel: payment")
		}
		return
	}
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount != n {
		panic("fishduel: payment")
	}
}

func mustHex(s string, n int) []byte {
	if len(s) != n*2 {
		panic("fishduel: hex")
	}
	for _, c := range s {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			panic("fishduel: hex")
		}
	}
	raw, err := hex.DecodeString(s)
	if err != nil || len(raw) != n {
		panic("fishduel: hex")
	}
	return raw
}

func atoi(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		panic("fishduel: note")
	}
	return n
}

func atoi64(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		panic("fishduel: note")
	}
	return n
}
